/**
 * 
      Retrieves comprehensive dashboard metrics for a specific collector.
      Returns both the requested period stats AND today's stats in a single response
      to optimize performance for dashboard rendering.

      **This is an internal endpoint** - not exposed to external users.
    
 * @summary Get collector dashboard metrics (period + today in single call)
 */
export type internalAnalyticsControllerGetCollectorDashboardMetricsResponse200 =
  {
    data: CollectorDashboardMetricsDto;
    status: 200;
  };

export type internalAnalyticsControllerGetCollectorDashboardMetricsResponseSuccess =
  internalAnalyticsControllerGetCollectorDashboardMetricsResponse200 & {
    headers: Headers;
  };
export type internalAnalyticsControllerGetCollectorDashboardMetricsResponse =
  internalAnalyticsControllerGetCollectorDashboardMetricsResponseSuccess;

export const getInternalAnalyticsControllerGetCollectorDashboardMetricsUrl = (
  collectorUserId: string,
  params: InternalAnalyticsControllerGetCollectorDashboardMetricsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/internal/transactions/analytics/collectors/${collectorUserId}/dashboard-metrics?${stringifiedParams}`
    : `/internal/transactions/analytics/collectors/${collectorUserId}/dashboard-metrics`;
};

export const internalAnalyticsControllerGetCollectorDashboardMetrics = async (
  collectorUserId: string,
  params: InternalAnalyticsControllerGetCollectorDashboardMetricsParams,
  options?: RequestInit,
): Promise<internalAnalyticsControllerGetCollectorDashboardMetricsResponse> => {
  return customInstance<internalAnalyticsControllerGetCollectorDashboardMetricsResponse>(
    getInternalAnalyticsControllerGetCollectorDashboardMetricsUrl(
      collectorUserId,
      params,
    ),
    {
      ...options,
      method: 'GET',
    },
  );
};

